/**
 * English name of each language, for prompting a model in the user's language.
 * The model needs the name spelled out — a BCP-47 tag alone is unreliable.
 */
export const promptLanguageName = (code) => {
  const entry = LANGUAGES.find(l => l.code === code);
  if (!entry) return 'English';
  if (code === 'zh-Hans') return 'Simplified Chinese';
  if (code === 'zh-Hant') return 'Traditional Chinese';
  return entry.english;
};

export const strings = {
  en, ko, ja, 'zh-Hans': zhHans, 'zh-Hant': zhHant, es, fr, de, pt, ru, vi, ar,
};

/** Maps a browser language tag onto one of ours. */
export const resolveLanguage = (tag) => {
  if (!tag) return 'en';
  const lower = String(tag).toLowerCase();
  if (lower.startsWith('zh')) {
    return /hant|tw|hk|mo/.test(lower) ? 'zh-Hant' : 'zh-Hans';
  }
  const base = lower.split('-')[0];
  const match = LANGUAGES.find(l => l.code.toLowerCase() === lower)
    || LANGUAGES.find(l => l.code.toLowerCase() === base);
  return match ? match.code : 'en';
};

export const detectLanguage = () => {
  const saved = localStorage.getItem('uiLanguage');
  if (saved && strings[saved]) return saved;
  const navLangs = (navigator.languages && navigator.languages.length)
    ? navigator.languages
    : [navigator.language];
  for (const tag of navLangs) {
    const resolved = resolveLanguage(tag);
    if (resolved !== 'en' || String(tag).toLowerCase().startsWith('en')) return resolved;
  }
  return 'en';
};

/** `{name}` placeholders are replaced from `vars`. */
export const translate = (lang, key, vars) => {
  const table = strings[lang] || strings.en;
  let value = table[key];
  if (value === undefined) value = strings.en[key];
  if (value === undefined) return key;
  if (!vars) return value;
  return value.replace(/\{(\w+)\}/g, (whole, name) => (
    Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : whole
  ));
};

export const I18nContext = createContext(null);

export const I18nProvider = ({ children }) => {
  const [lang, setLangState] = useState(() => detectLanguage());

  const dir = useMemo(
    () => (LANGUAGES.find(l => l.code === lang)?.dir || 'ltr'),
    [lang]
  );

  useEffect(() => {
    localStorage.setItem('uiLanguage', lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = dir;
  }, [lang, dir]);

  const t = useCallback((key, vars) => translate(lang, key, vars), [lang]);

  const value = useMemo(() => ({ lang, setLang: setLangState, t, dir }), [lang, t, dir]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
};

export const useI18n = () => {
  const ctx = useContext(I18nContext);
  // Falling back keeps components usable outside the provider (e.g. in tests).
  if (!ctx) return { lang: 'en', setLang: () => {}, dir: 'ltr', t: (k, v) => translate('en', k, v) };
  return ctx;
};
